export const ARTICLES_DATA: Article[] = [...ARTICLES_BATCH_1, ...ARTICLES_BATCH_2, ...ARTICLES_BATCH_3, ...ARTICLES_BATCH_4, ...ARTICLES_BATCH_5, ...ARTICLES_BATCH_6, ...ARTICLES_BATCH_7, ...ARTICLES_BATCH_8, ...ARTICLES_BATCH_9, ...ARTICLES_BATCH_10, ...ARTICLES_BATCH_11, ...ARTICLES_BATCH_12, ...ARTICLES_BATCH_13, ...ARTICLES_BATCH_14, ...ARTICLES_BATCH_15, ...ARTICLES_BATCH_16, ...ARTICLES_BATCH_17, ...ARTICLES_BATCH_18];

export function getArticleBySlug(targetSlug: string): Article | undefined {
  if (!targetSlug) return ARTICLES_DATA[0];
  
  const exact = ARTICLES_DATA.find((a) => a.slug === targetSlug);
  if (exact) return exact;

  const cleanTarget = targetSlug.replace(/-\d+$/, '').toLowerCase();
  const partial = ARTICLES_DATA.find((a) => a.slug.toLowerCase().includes(cleanTarget) || cleanTarget.includes(a.slug.toLowerCase()));
  if (partial) return partial;

    return ARTICLES_DATA[0];
}
